def compute(vars):
    cost_million = vars["v1"]
    shares_million = vars["v2"]

    if shares_million == 0:
        return None

    price_per_share = cost_million / shares_million
    return {
        "value": price_per_share,
        "trace": {
            "cost_million": cost_million,
            "shares_million": shares_million,
            "output_meta": {
                "currency": "USD",
                "scale": "ones",
                "unit": "USD per share"
            }
        }
    }
